const runnerBase = process.env.AUTOMATION_RUNNER_BASE_URL;
if (!runnerBase) {
  throw new Error('AUTOMATION_RUNNER_BASE_URL env var is required');
}
let runnerUrl;
try {
  runnerUrl = new URL(runnerBase);
} catch {
  throw new Error('AUTOMATION_RUNNER_BASE_URL must be a valid absolute URL');
}
const githubWebhookSecret = process.env.GITHUB_WEBHOOK_SECRET;
if (!githubWebhookSecret) {
  throw new Error('GITHUB_WEBHOOK_SECRET env var is required');
}
const signatureHeader = $json.headers?.['x-hub-signature-256'] ?? $json.headers?.['X-Hub-Signature-256'] ?? '';
if (!signatureHeader) {
  throw new Error('Missing X-Hub-Signature-256 header');
}
const rawBodyValue = $json.rawBody ?? '';
const rawBody = typeof rawBodyValue === 'string' ? rawBodyValue : JSON.stringify(rawBodyValue);
const encoder = new TextEncoder();
const secretKey = await crypto.subtle.importKey(
  'raw',
  encoder.encode(githubWebhookSecret),
  { name: 'HMAC', hash: 'SHA-256' },
  false,
  ['sign'],
);
const digestBuffer = await crypto.subtle.sign('HMAC', secretKey, encoder.encode(rawBody));
const digestHex = Array.from(new Uint8Array(digestBuffer))
  .map((byte) => byte.toString(16).padStart(2, '0'))
  .join('');
const expectedSignature = `sha256=${digestHex}`;
const providedSignature = String(signatureHeader);
const timingSafeEqual = (left, right) => {
  const leftBytes = encoder.encode(left);
  const rightBytes = encoder.encode(right);
  if (leftBytes.length !== rightBytes.length) {
    return false;
  }
  let mismatch = 0;
  for (let index = 0; index < leftBytes.length; index += 1) {
    mismatch |= leftBytes[index] ^ rightBytes[index];
  }
  return mismatch === 0;
};
if (!timingSafeEqual(expectedSignature, providedSignature)) {
  throw new Error('Invalid X-Hub-Signature-256 signature');
}
const runnerToken = process.env.AUTOMATION_RUNNER_TOKEN;
const headers = {
  'Content-Type': 'application/json',
  ...(runnerToken ? { Authorization: `Bearer ${runnerToken}` } : {}),
};
const payload = $json.body ?? $json;
const githubEvent = $json.headers?.['x-github-event'] ?? $json.headers?.['X-GitHub-Event'] ?? payload.event ?? 'unknown';
const isPrIssueComment = githubEvent === 'issue_comment' && payload.issue?.pull_request;
const reviewEvents = new Set(['pull_request_review', 'pull_request_review_comment']);
const prNumber = payload.pull_request?.number ?? payload.issue?.number ?? null;
const route = githubEvent === 'push'
  ? 'commit-summarizer'
  : githubEvent === 'pull_request'
    ? 'pr-review-first-pass'
    : githubEvent === 'issues'
      ? 'bug-triage'
      : (reviewEvents.has(githubEvent) || isPrIssueComment)
        ? 'pr-autofinish'
        : 'ignore';
const reportRelativePath = `github-events/${new Date().toISOString().replace(/[:]/g, '-')}-${githubEvent}.json`;
const writeResponse = await fetch(new URL('/reports/write', runnerUrl), {
  method: 'POST',
  headers,
  body: JSON.stringify({ relativePath: reportRelativePath, content: JSON.stringify({ githubEvent, route, payload }, null, 2) }),
});
if (!writeResponse.ok) throw new Error(`reports/write failed: ${writeResponse.status}`);
const putResponse = await fetch(new URL('/context/last-github-event', runnerUrl), {
  method: 'PUT',
  headers,
  body: JSON.stringify({ value: { githubEvent, route, reportRelativePath, receivedAt: new Date().toISOString(), prNumber } }),
});
if (!putResponse.ok) {
  const body = await putResponse.text();
  throw new Error(`context update failed: ${putResponse.status} ${body}`);
}
let jobResult = null;
if (route === 'pr-autofinish' && prNumber) {
  const jobResponse = await fetch(new URL('/jobs', runnerUrl), {
    method: 'POST',
    headers,
    body: JSON.stringify({ action: 'pr_autofinish', mode: 'async', args: [String(prNumber)], dedupeKey: `pr-autofinish-${prNumber}` }),
  });
  const raw = await jobResponse.text();
  if (!jobResponse.ok && jobResponse.status !== 202) {
    throw new Error(`runner pr_autofinish failed: ${jobResponse.status} ${raw}`);
  }
  jobResult = raw ? JSON.parse(raw) : null;
}
return [{ json: { ok: true, githubEvent, route, prNumber, reportRelativePath, jobResult } }];
